const listRecoverableExtractionJobs = `-- name: ListRecoverableExtractionJobs :many
SELECT id, document_id, document_version, epoch, state, initialization_complete
FROM relation_extraction_jobs
WHERE state IN ('pending', 'initializing', 'running')
  AND (lease_until IS NULL OR lease_until < ?)
  AND id > ?
ORDER BY id
LIMIT ?
`

type ListRecoverableExtractionJobsParams struct {
	LeaseUntil sql.NullTime `json:"lease_until"`
	ID         string       `json:"id"`
	Limit      int32        `json:"limit"`
}

type ListRecoverableExtractionJobsRow struct {
	ID                     string `json:"id"`
	DocumentID             string `json:"document_id"`
	DocumentVersion        int32  `json:"document_version"`
	Epoch                  int32  `json:"epoch"`
	State                  string `json:"state"`
	InitializationComplete bool   `json:"initialization_complete"`
}

// 恢复扫描：需要有人接手的作业。
//
// ⭐ state 白名单里**故意没有** paused 和 budget_exhausted：
// 那两个是**用户或预算做出的决定**，不是故障。自动把它们捡回来跑，
// 等于系统擅自推翻了一次显式的停止——而用户会看到一个自己明明暂停过的
// 作业又开始花钱。
//
// 条件是"没人持有，或者持有者的租约已经过期"。id 收尾做游标分页，
// 避免一次扫描把成千上万行拉回来。
// ⚠️ pending 必须在列：那是 enable 登记的「等待文档就绪」意图，
// 正等着恢复扫描来补 items。漏掉它的表现是用户开启了抽取、界面显示已开启，
// 而那个作业永远不会开始——没有报错，没有进度，什么都不发生。
func (q *Queries) ListRecoverableExtractionJobs(ctx context.Context, arg ListRecoverableExtractionJobsParams) ([]ListRecoverableExtractionJobsRow, error) {
	rows, err := q.db.QueryContext(ctx, listRecoverableExtractionJobs, arg.LeaseUntil, arg.ID, arg.Limit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListRecoverableExtractionJobsRow{}
	for rows.Next() {
		var i ListRecoverableExtractionJobsRow
		if err := rows.Scan(
			&i.ID,
			&i.DocumentID,
			&i.DocumentVersion,
			&i.Epoch,
			&i.State,
			&i.InitializationComplete,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

